try{csrf_pruefen($_POST["csrf_token"]??null);berechtigung_pruefen(["administrator"]);$id=positive_id($_POST["rechnung_id"]??null,"Rechnung");$grund=trim((string)($_POST["grund"]??""));if($grund===""||mb_strlen($grund)>1000)throw new EingabeException("Ein Stornogrund ist erforderlich.");$pdo->beginTransaction();$stmt=$pdo->prepare("SELECT rechnungsnummer,storniert_am FROM rechnungen WHERE id=? FOR UPDATE");$stmt->execute([$id]);$r=$stmt->fetch();if(!$r)throw new EingabeException("Rechnung wurde nicht gefunden.");if($r["storniert_am"])throw new EingabeException("Diese Rechnung ist bereits storniert.");$pdo->prepare("UPDATE rechnungen SET storniert_am=NOW(),storniert_von=?,storno_grund=? WHERE id=?")->execute([aktuelle_benutzer_id(),$grund,$id]);$pdo->prepare("UPDATE rechnung_geraete SET storniert_am=NOW() WHERE rechnung_id=?")->execute([$id]);audit_protokollieren($pdo,"rechnung_storniert","rechnung",$id,["rechnungsnummer"=>$r["rechnungsnummer"],"grund"=>$grund]);$pdo->commit();flash_setzen("success","Die Rechnung wurde nachvollziehbar storniert und bleibt im Archiv erhalten.");}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash_setzen("error",$e instanceof EingabeException?$e->getMessage():"Die Rechnung konnte nicht storniert werden.");}weiterleiten("rechnungsarchiv.php");
